import { describe, expect, it } from 'vitest';
import { FEE_BPS } from '../constants';
import { buildSettlementVectors, SETTLEMENT_VECTORS_VERSION } from './vectors';

/**
 * The guard on the shared file: it has to still say what this code says.
 *
 * Without this the parity test is one-sided — Rust would keep agreeing with a file nobody
 * regenerated, which is a slower version of the drift the file exists to prevent.
 *
 * It is a file snapshot rather than a build script because the file has two readers and only
 * one of them speaks TypeScript: a snapshot is regenerated by the same tool that checks it
 * (`pnpm --filter @sporim/domain vectors`), and a plain Node script could not import this
 * package at all — the sources are written for a bundler, without file extensions. The path is
 * relative to this file and stated as a string for the same reason the package has no other
 * Node import: this package must stay reusable where `node:path` does not exist.
 */
const VECTORS_PATH = '../../test-vectors/settlement.v1.json';
const serialized = `${JSON.stringify(buildSettlementVectors(), null, 2)}\n`;

describe('settlement vectors', () => {
  it('matches the committed file, byte for byte', async () => {
    // If this fails after an intentional change: pnpm --filter @sporim/domain vectors
    await expect(serialized).toMatchFileSnapshot(VECTORS_PATH);
  });

  const committed = JSON.parse(serialized) as ReturnType<typeof buildSettlementVectors>;

  it('carries its version and the fee it was generated under', () => {
    expect(committed.version).toBe(SETTLEMENT_VECTORS_VERSION);
    expect(committed.feeBps).toBe(FEE_BPS);
  });

  it('keeps money as strings, because JSON numbers are doubles', () => {
    for (const vector of committed.cases) {
      for (const amount of Object.values(vector.expected)) {
        expect(typeof amount).toBe('string');
      }
      expect(typeof vector.input.stakeCreator).toBe('string');
    }
  });

  /*
   * The invariant the on-chain side has to hold as well: a settlement moves the pot and
   * nothing else. Vault in, vault out, no third party inventing a lamport.
   */
  it('never pays out more or less than the pot', () => {
    for (const vector of committed.cases) {
      const paid =
        BigInt(vector.expected.toCreator) +
        BigInt(vector.expected.toOpponent) +
        BigInt(vector.expected.toTreasury) +
        BigInt(vector.expected.toReferee);
      expect(paid, vector.name).toBe(BigInt(vector.expected.pot));
    }
  });

  it('charges nothing on a refund or a draw', () => {
    const free = committed.cases.filter(
      (vector) => vector.input.outcome === 'refund' || vector.input.outcome === 'draw',
    );
    expect(free.length).toBeGreaterThan(0);
    for (const vector of free) {
      expect(vector.expected.fee, vector.name).toBe('0');
      expect(vector.expected.toReferee, vector.name).toBe('0');
    }
  });

  it('marks which cases the first on-chain slice is expected to reproduce', () => {
    const onChain = committed.cases.filter((vector) => vector.onChain);
    const notYet = committed.cases.filter((vector) => !vector.onChain);
    // Both halves matter: the Rust test would pass vacuously if the first were empty, and the
    // second is the list the next slice has to work through.
    expect(onChain.length).toBeGreaterThan(5);
    expect(notYet.length).toBeGreaterThan(0);
    for (const vector of notYet) {
      const { format, outcome, ruledByReferee } = vector.input;
      expect(format === 'commit' || outcome === 'refund' || ruledByReferee, vector.name).toBe(true);
    }
  });
});
